import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Observable } from 'rxjs';
import { AppService, AppState } from '../../core/services/app.service';
import { AuthService } from '../../core/services/auth.service';
import { Product, SaleItem } from '../../core/models';

@Component({
  selector: 'app-sales',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './sales.component.html'
})
export class SalesComponent {
  appState$: Observable<AppState>;
  searchTerm = '';
  customerName = '';
  paymentMethod: 'cash' | 'card' | 'other' = 'cash';

  constructor(
    private appService: AppService,
    private authService: AuthService
  ) {
    this.appState$ = this.appService.appState$;
  }

  getFilteredProducts(appState: AppState): Product[] {
    return appState.products.filter(product =>
      product.stock > 0 && (
        product.name.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
        product.sku.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
        (product.barcode && product.barcode.includes(this.searchTerm))
      )
    );
  }

  addToSale(product: Product): void {
    const quantity = 1;
    const unitPrice = quantity >= product.wholesaleMinQuantity ? product.wholesalePrice : product.price;

    const saleItem: SaleItem = {
      productId: product.id,
      product,
      quantity,
      price: unitPrice,
      total: unitPrice,
    };

    this.appService.addToSale(saleItem);
  }

  updateQuantity(productId: string, quantity: number): void {
    if (quantity <= 0) {
      this.appService.removeFromSale(productId);
    } else {
      const appState = this.appService.appStateBehaviorSubject.value;
      const product = appState.products.find((p: Product) => p.id === productId);
      if (product) {
        const unitPrice = quantity >= product.wholesaleMinQuantity ? product.wholesalePrice : product.price;
        this.appService.updateSaleQuantity(productId, quantity, unitPrice);
      }
    }
  }

  removeFromSale(productId: string): void {
    this.appService.removeFromSale(productId);
  }

  getSubtotal(appState: AppState): number {
    return appState.currentSale.reduce((sum, item) => sum + item.total, 0);
  }

  getTax(appState: AppState): number {
    return this.getSubtotal(appState) * 0.18;
  }

  getTotal(appState: AppState): number {
    return this.getSubtotal(appState) + this.getTax(appState);
  }

  completeSale(appState: AppState): void {
    if (appState.currentSale.length === 0) return;
    // Permission check: only admin or sales can complete a sale
    const user = this.authService.getCurrentUser();
    if (!user || (user.role !== 'admin' && user.role !== 'sales')) {
      alert("You don't have permission to complete sales. Please sign in as Sales or Admin.");
      return;
    }

    const saleData = {
      paymentMethod: this.paymentMethod,
      customerName: this.customerName,
    };

    this.appService.createSale(saleData, appState.currentSale).subscribe({
      next: () => {
        alert('Sale completed successfully!');
        this.customerName = '';
        this.searchTerm = '';
      },
      error: (err) => {
        const status = err?.status;
        if (status === 401) {
          alert('Session expired. Please log in again.');
        } else if (status === 403) {
          alert("You don't have permission to complete sales. Please sign in as Sales or Admin.");
        } else if (status === 400) {
          const message = err?.error?.message || err?.error?.error || 'Request invalid.';
          alert(`Failed to complete sale: ${message}`);
        } else {
          alert('Failed to complete sale. Please try again.');
        }
      }
    });
  }
}
<div class="max-w-7xl mx-auto px-4" *ngIf="appState$ | async as appState">
  <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
    <!-- Left: products -->
    <div class="lg:col-span-2">
      <div class="bg-white rounded-2xl shadow-sm border border-gray-200 p-4">
        <!-- search -->
        <div class="relative mb-4">
          <div class="pointer-events-none absolute inset-y-0 left-3 flex items-center">
            <svg class="h-4 w-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="11" cy="11" r="7" stroke-width="1.6"/><path stroke-linecap="round" stroke-width="1.6" d="M20 20l-3.5-3.5"/></svg>
          </div>
          <input type="text" [(ngModel)]="searchTerm" placeholder="Search or scan products to add to sale..."
                 class="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
        </div>

        <!-- Product cards -->
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-1">
          <div *ngFor="let product of getFilteredProducts(appState)" class="border border-gray-200 rounded-xl overflow-hidden bg-white hover:shadow-md transition">
            <div class="h-40 bg-gray-100">
              <img *ngIf="product.imageUrls?.length" [src]="product.imageUrls[0]" [alt]="product.name" class="w-full h-full object-cover" />
            </div>
            <div class="p-3">
              <div class="flex items-center justify-between">
                <div class="text-sm font-semibold text-gray-900 truncate">{{ product.name }}</div>
                <button (click)="$event.stopPropagation(); addToSale(product)" title="Add" class="p-1.5 rounded-full bg-blue-600 text-white hover:bg-blue-700">+
                </button>
              </div>
              <div class="text-xs text-gray-600">{{ product.size }} – {{ product.color }}</div>
              <div class="text-xs text-blue-600">{{ product.barcode || product.sku }}</div>
              <div class="mt-1 text-green-600 font-semibold">₹{{ product.price.toFixed(2) }}</div>
              <div class="text-xs text-gray-500 text-right">Stock: {{ product.stock }}</div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Right: current sale -->
    <div>
      <div class="bg-white rounded-2xl shadow-sm border border-gray-200 p-4">
        <div class="flex items-center gap-2 text-gray-900 font-semibold mb-3">
          <svg class="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4m0 0L7 13m0 0l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17M17 13v6a2 2 0 01-2 2H9a2 2 0 01-2-2v-6m8 0V9a2 2 0 00-2-2H9a2 2 0 00-2 2v4.01"/></svg>
          <span>Current Sale</span>
        </div>

        <div class="space-y-3 mb-4 max-h-[45vh] overflow-y-auto pr-1">
          <p *ngIf="appState.currentSale.length === 0" class="text-gray-500 text-center py-6">No items in current sale</p>

          <div *ngFor="let item of appState.currentSale" class="p-3 bg-gray-50 rounded-lg border border-gray-200">
            <div class="flex items-start justify-between">
              <div class="min-w-0">
                <div class="font-medium text-gray-900 truncate">{{ item.product.name }}</div>
                <div class="text-xs text-gray-600">{{ item.product.size }} – {{ item.product.color }}</div>
                <div class="text-sm font-semibold text-green-600">₹{{ item.price.toFixed(2) }} each</div>
              </div>
              <div class="flex items-center gap-2 ml-3">
                <button (click)="updateQuantity(item.productId, item.quantity - 1)" class="p-1 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded">
                  <svg class="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 12H4"/></svg>
                </button>
                <input type="number" [min]="1" [max]="item.product.stock + item.quantity" [value]="item.quantity"
                       (change)="updateQuantity(item.productId, +$any($event.target).value)"
                       class="w-14 text-center font-medium border border-gray-300 rounded px-2 py-1 focus:ring-2 focus:ring-blue-500 focus:border-transparent"/>
                <button (click)="updateQuantity(item.productId, item.quantity + 1)" class="p-1 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded">
                  <svg class="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 6v12m6-6H6"/></svg>
                </button>
                <button (click)="removeFromSale(item.productId)" class="p-1 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded">
                  <svg class="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                </button>
              </div>
            </div>
          </div>
        </div>

        <div class="border-t border-gray-200 pt-3 space-y-2">
          <div class="flex justify-between text-sm"><span>Subtotal:</span><span>₹{{ getSubtotal(appState).toFixed(2) }}</span></div>
          <div class="flex justify-between text-sm"><span>Tax (18% GST):</span><span>₹{{ getTax(appState).toFixed(2) }}</span></div>
          <div class="flex justify-between text-lg font-bold border-t border-gray-200 pt-2"><span>Total:</span><span class="text-green-600">₹{{ getTotal(appState).toFixed(2) }}</span></div>
        </div>

        <div class="mt-4 space-y-3">
          <input type="text" placeholder="Customer name (optional)" [(ngModel)]="customerName"
                 class="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
          <select [(ngModel)]="paymentMethod" class="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
            <option value="cash">Cash</option>
            <option value="card">Card</option>
            <option value="other">Other</option>
          </select>
          <button (click)="completeSale(appState)" class="w-full bg-blue-600 text-white py-3 px-4 rounded-lg hover:bg-blue-700 transition-colors font-medium">
            Complete Sale - Foreign Fits
          </button>
        </div>
      </div>
    </div>
  </div>
</div>
